import { render } from '@solidjs/web';
import { createMemo, Errored, Loading } from 'solid-js';

let attempts = 0;
async function fetchReport() {
  await new Promise((resolve) => setTimeout(resolve, 300));
  if (++attempts === 1)
    throw new Error('The report service is temporarily unavailable');
  return 'Report ready';
}
function Result() {
  const report = createMemo(fetchReport);
  return (
    <Loading fallback={<p>Loading report...</p>}>
      <p>{report()}</p>
    </Loading>
  );
}
function App() {
  return (
    <>
      <h1>Async errors</h1>
      <Errored
        fallback={(error, retry) => (
          <div role="alert">
            <p>Add a message and retry button here.</p>
          </div>
        )}
      >
        <Result />
      </Errored>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

import { render } from '@solidjs/web';
import { createMemo, Errored, Loading } from 'solid-js';

let attempts = 0;
async function fetchReport() {
  await new Promise((resolve) => setTimeout(resolve, 300));
  if (++attempts === 1)
    throw new Error('The report service is temporarily unavailable');
  return 'Report ready';
}
function Result() {
  const report = createMemo(fetchReport);
  return (
    <Loading fallback={<p>Loading report...</p>}>
      <p>{report()}</p>
    </Loading>
  );
}
function App() {
  return (
    <>
      <h1>Async errors</h1>
      <Errored
        fallback={(error, retry) => (
          <div role="alert">
            <p>{error().message}</p>
            <button onClick={retry}>Retry report</button>
          </div>
        )}
      >
        <Result />
      </Errored>
    </>
  );
}

render(() => <App />, document.getElementById('app'));
